window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[78]={"id":"078","numero":78,"titre":"Addiction aux drogues (cannabis, cocaïne, amphétamines, opiacés)","objectifs":[{"id":"78-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","contenu":"<div class=\"notion-course\"><h4>Produit, usage et trouble</h4><p>L’addiction ne se définit pas par la seule prise d’un produit : rechercher perte de contrôle, priorité croissante, poursuite malgré dommages et retentissement. Toute exposition peut présenter des risques sans démontrer un trouble de l’usage.</p><table><thead><tr><th>Famille</th><th>Repères</th></tr></thead><tbody><tr><td>Cannabis</td><td>Produits de Cannabis sativa, teneurs variables en THC.</td></tr><tr><td><span class=\"nc-pink nc-bold\">Cocaïne</span></td><td>Stimulant issu des feuilles de coca, poudre ou base.</td></tr><tr><td>Amphétaminiques</td><td><span class=\"nc-yellow_bg\">Amphétamine</span>, <span class=\"nc-pink nc-bold\">méthamphétamine</span>, MDMA.</td></tr><tr><td>Opioïdes</td><td>Famille incluant opiacés <span class=\"nc-yellow_bg\">naturels</span>, dérivés <span class=\"nc-yellow_bg\">semi-synthétiques</span> et <span class=\"nc-yellow_bg\">produits synthétiques</span>.</td></tr><tr><td>NPS</td><td>Nouveaux produits psychoactifs : cannabinoïdes, <span class=\"nc-yellow_bg\">cathinones</span>, opioïdes et autres. Ni nouveauté ni vente en ligne ne garantit légalité ou sécurité.</td></tr></tbody></table></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details><details data-lisa-review=\"20261014\"><summary>Situations de départ LiSA vérifiées</summary><p>Attendus consultés sur LiSA 2026 le 14 octobre 2026, reformulés pour la révision.</p><ul><li><a href=\"https://livret.uness.fr/lisa/2026/Prise_volontaire_ou_involontaire_d%27un_toxique_ou_d%27un_m%C3%A9dicament_potentiellement_toxique_SDD-340\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 340 · Prise d’un toxique ou médicament potentiellement toxique</a><ul><li>Dater et quantifier l’exposition, reconnaître les toxidromes, évaluer la gravité et considérer un antidote adapté.</li><li>Organiser surveillance et orientation, évaluer intention suicidaire ou maltraitance et solliciter le centre antipoison selon la situation.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Premi%C3%A8re_consultation_d%27addictologie_SDD-292\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 292 · Première consultation d’addictologie</a><ul><li>Caractériser usage nocif, dépendance ou addiction comportementale selon la classification utilisée ; rechercher sevrage, complications et comorbidités.</li><li>Évaluer les conséquences familiales, sociales et professionnelles, fixer des objectifs partagés et orienter ou proposer une substitution selon indication.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_addictologie_SDD-293\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 293 · Consultation de suivi addictologie</a><ul><li>Rechercher manque, nouveaux symptômes, complications et comorbidités ; apprécier efficacité, tolérance et qualité de vie.</li><li>Adapter prescription et accompagnement social ; la valorisation du stage inclut psychothérapie, entretien motivationnel et soutien des proches avec respect de la confidentialité.</li></ul></li></ul><p>Les liens ciblent les compétences pertinentes pour cet item ; ils ne signifient pas que la fiche couvre à elle seule toute la situation de départ.</p></details>","frequence":0},{"id":"78-2","rang":"A","rubrique":"Définition","titre":"Connaître les principes actifs","contenu":"<div class=\"notion-course\"><h4>Principes actifs et cibles</h4><table><thead><tr><th>Famille</th><th>Repère</th></tr></thead><tbody><tr><td>Cannabis</td><td>THC : agoniste partiel cannabinoïde, notamment <span class=\"nc-red nc-bold\">CB1</span>. Pharmacologie complexe du CBD, non réductible à « antagoniste <span class=\"nc-red nc-bold\">CB1</span>/agoniste CB2 ».</td></tr><tr><td><span class=\"nc-pink nc-bold\">Cocaïne</span></td><td><span class=\"nc-pink nc-bold\">Chlorhydrate</span> et forme base ; inhibition de recapture monoaminergique.</td></tr><tr><td>Amphétaminiques</td><td><span class=\"nc-yellow_bg\">Amphétamine</span>, <span class=\"nc-pink nc-bold\">méthamphétamine</span>, <span class=\"nc-pink nc-bold\">MDMA</span> : effets monoaminergiques, dont sérotoninergiques pour <span class=\"nc-pink nc-bold\">MDMA</span>.</td></tr><tr><td>Opioïdes</td><td>Morphine/codéine naturelles ; <span class=\"nc-pink nc-bold\">héroïne</span>, oxycodone et <span class=\"nc-pink_bg\">buprénorphine</span> <span class=\"nc-yellow_bg\">semi-synthétiques</span> ; <span class=\"nc-pink_bg\">méthadone</span>, fentanyl et tramadol synthétiques.</td></tr><tr><td>NPS</td><td><span class=\"nc-yellow_bg\">Cathinones</span> (3-MMC, <span class=\"nc-pink_bg\">méphédrone</span>…), cannabinoïdes et opioïdes de synthèse ; composition et puissance incertaines.</td></tr><tr><td>Autres</td><td>LSD/psilocybine : hallucinogènes ; kétamine : dissociatif antagoniste NMDA ; GHB et précurseur GBL : dépresseurs.</td></tr></tbody></table></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"78-3","rang":"A","rubrique":"Définition","titre":"Connaître les modes de consommation et leurs effets","contenu":"<div class=\"notion-course\"><p>Les drogues se classent en <strong>trois grandes catégories selon leur effet</strong> sur le système nerveux central — c'est la grille de lecture fondamentale de l'item.</p>\n      <table>\n        <thead><tr><th>Classe</th><th>Effets</th><th>Exemples</th><th>Risque principal</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Perturbateurs / hallucinogènes</span></td>\n            <td><span>Désorientation</span> temporo-spatiale ; altération des perceptions sensorielles ; distorsion de la réalité, <span><span class=\"nc-purple_bg nc-bold\">hallucinations</span></span></td>\n            <td>Cannabis ; champignons hallucinogènes ; <span>kétamine</span> ; LSD ; MDMA/ecstasy ; PCP</td>\n            <td><span>Troubles psychiatriques</span> : bad trips, dépersonnalisation, psychoses</td>\n          </tr>\n          <tr>\n            <td><span>Dépresseurs</span></td>\n            <td>Ralentissement cérébral et moteur ; baisse de la vigilance et des réflexes ; effet anxiolytique, parfois euphorique</td>\n            <td><span>Alcool</span> ; GHB ; héroïne</td>\n            <td><span><span class=\"nc-orange_bg\">Dépression</span> respiratoire</span> ; forte dépendance ; risque d'overdose</td>\n          </tr>\n          <tr>\n            <td><span>Stimulants</span></td>\n            <td>Excitation, agitation, hausse de l'énergie ; accélération du <span class=\"nc-orange nc-bold\">rythme</span> <span class=\"nc-orange nc-bold\">cardiaque</span> ; effet euphorisant et désinhibant</td>\n            <td>Amphétamines ; <span class=\"nc-pink nc-bold\">cocaïne</span> ; <span class=\"nc-pink nc-bold\">méthamphétamine</span></td>\n            <td><span>Hyperstimulation <span class=\"nc-orange nc-bold\">cardiaque</span> et cérébrale</span> : <span>IDM</span>, <span>AVC</span>, psychoses (<span class=\"nc-orange_bg\">paranoïa</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Modes de consommation</strong> selon les substances : <span>fumé</span> (joint, pipe à eau) ; <span>ingéré</span> (space cake, comprimé) ; <span>sniffé</span> par voie intranasale ; <span>injecté</span> par voie intraveineuse ; <span>inhalé</span> ou vaporisé.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le mélange de substances de classes différentes augmente fortement le risque de toxicité et d'overdose.</div><div class=\"callout\"><p>Les catégories se recouvrent : MDMA a des effets stimulants et empathogènes, kétamine des effets dissociatifs. Mélanger des dépresseurs menace particulièrement la respiration.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"78-4","rang":"A","rubrique":"Définition","titre":"Connaître les voies d’administration","contenu":"<div class=\"notion-course\"><p>La <strong>voie d'administration</strong> conditionne la rapidité d'apparition et la durée des effets : plus l'absorption est rapide (<span class=\"nc-red_bg\">inhalation</span>, <span class=\"nc-red_bg\">voie IV</span>), plus l'effet est intense, bref et addictogène.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Voies d'administration</th></tr></thead>\n        <tbody>\n          <tr><td><span>Cannabis</span></td><td>\n            <strong>Fumé</strong> +++ : joint (mélangé au <span>tabac</span>), pipe à eau (bang)<br>\n            <strong>Ingéré :</strong> space cake (plus rare)<br>\n            <strong>Vaporisé</strong> ou consommé en cigarette électronique (<span class=\"nc-yellow_bg\">cannabinoïdes de synthèse</span>)\n          </td></tr>\n          <tr><td><span><span class=\"nc-pink nc-bold\">Cocaïne</span></span></td><td>Poudre : surtout voie nasale, parfois IV. Base : fumée, parfois injectée. Voie orale possible mais moins habituelle ; ingestion de sachets : intoxication massive possible en cas de rupture.</td></tr>\n          <tr><td><span>Amphétamines</span></td><td>\n            <span class=\"nc-yellow_bg\">MDMA</span> : poudre sniffée par voie intranasale, injectée, ou comprimé avalé (« gober »)\n          </td></tr>\n          <tr><td><span>Opiacés</span> (héroïne)</td><td>\n            Voie nasale (sniff) ; fumée ; voie intraveineuse (shoot, fix)\n          </td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Cathinones</span> de synthèse</span></td><td>\n            Voies multiples : orale (drop), <span class=\"nc-blue_bg\">inhalée</span>, intranasale, IV (slam), intrarectale (plug)\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège — la voie injectable.</strong> La voie intraveineuse et le <span>slam</span> (injection en contexte sexuel) exposent au risque infectieux majeur : <span><span class=\"nc-purple_bg\">VIH</span>, <span class=\"nc-purple_bg\">VHB</span>, <span class=\"nc-purple_bg\">VHC</span></span>, <span class=\"nc-orange_bg\">abcès</span>, <span>endocardite</span> (voir « Principales complications »).</div><div class=\"callout\"><p>Après ingestion, le début retardé peut conduire à répéter les prises avant l’effet maximal. Une voie sans injection n’exclut pas une intoxication grave.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"78-5","rang":"B","rubrique":"Définition","titre":"Connaître la prévalence de l’utilisation des principales drogues psychoactives","contenu":"<div class=\"notion-course\"><h4>OFDT : année et indicateur</h4><table><thead><tr><th>Substance</th><th>Adultes 18–64 ans, enquête 2023</th></tr></thead><tbody><tr><td>Cannabis</td><td>50,4 % ont expérimenté ; substance illicite la plus utilisée.</td></tr><tr><td><span class=\"nc-pink nc-bold\">Cocaïne</span></td><td>9,4 % expérimentation ; 2,7 % usage dans l’année.</td></tr><tr><td><span class=\"nc-yellow_bg\">MDMA</span>/ecstasy</td><td>8,2 % expérimentation.</td></tr><tr><td>Héroïne</td><td>2,0 % expérimentation ; 0,3 % dans l’année.</td></tr></tbody></table><p>Usage dans l’année ≠ usage régulier. Les anciennes valeurs 47 %, 5,5 % ou 1,3 % viennent d’enquêtes antérieures. La <span class=\"nc-pink nc-bold\">méthamphétamine</span> est moins diffusée en France que d’autres stimulants, avec des contextes locaux particuliers.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.ofdt.fr/sites/ofdt/files/2025-01/dacc_2024.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">OFDT · Drogues et addictions, chiffres clés 2025</a></li><li><a href=\"https://www.ofdt.fr/cannabis-resine-herbe-huile-cbd-synthese-des-connaissances-1724\" target=\"_blank\" rel=\"noopener noreferrer\">OFDT · Cannabis, synthèse des connaissances</a></li></ul><p></p></details>","frequence":0},{"id":"78-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’intoxication aiguë","contenu":"<div class=\"notion-course\"><h4>Intoxication aiguë : toxidromes</h4><table><thead><tr><th>Produit</th><th>Signes et dangers</th></tr></thead><tbody><tr><td>Cannabis</td><td><span class=\"nc-green_bg\">Euphorie</span>, troubles attentionnels/perceptifs, panique, tachycardie, conjonctives rouges ; parfois psychose, vomissements ou trouble de vigilance.</td></tr><tr><td>Stimulants</td><td>Agitation, <span class=\"nc-red nc-bold\">mydriase</span>, tachycardie, hypertension, douleur thoracique, hyperthermie, convulsions. Toute hyperthermie n’est pas un syndrome sérotoninergique.</td></tr><tr><td>Opioïdes</td><td>Baisse de conscience, bradypnée/apnée, souvent myosis ; son absence n’exclut pas la surdose.</td></tr><tr><td>GHB/GBL</td><td>Sédation parfois brutale, coma, <span class=\"nc-orange_bg\">dépression</span> respiratoire, aggravés par alcool et autres dépresseurs.</td></tr><tr><td>Kétamine</td><td>Dissociation, troubles perceptifs, agitation ou sédation ; accidents et complications respiratoires possibles.</td></tr><tr><td>Hallucinogènes</td><td>Distorsions perceptives, panique, agitation ; rechercher produit différent/associé devant gravité somatique.</td></tr></tbody></table><div class=\"callout\"><p>Conscience, respiration, température, glycémie et complications : la dose déclarée et les pupilles ne suffisent pas.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"78-7","rang":"A","rubrique":"Définition","titre":"Connaître les comorbidités psychiatriques et addictives","contenu":"<div class=\"notion-course\"><p>Il faut distinguer la <strong>comorbidité</strong> (trouble préexistant ou durablement associé à l'addiction) de la <strong>complication</strong> (trouble <em>induit</em> par la consommation — voir « Principales complications »).</p>\n      <table>\n        <thead><tr><th>Type</th><th>Comorbidités fréquemment associées</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Psychiatriques</span></td>\n            <td>\n              <strong><span><span class=\"nc-red_bg\">Schizophrénie</span></span> :</strong> chez le sujet vulnérable, le cannabis peut <span><span class=\"nc-red nc-bold\">précipiter l'entrée dans la maladie</span></span> et <span class=\"nc-red nc-bold\">aggraver</span> son évolution<br>\n              <strong><span><span class=\"nc-red_bg\">Trouble bipolaire</span></span> :</strong> aggravé par le cannabis (épisodes maniaques, cycles rapides)<br>\n              <strong>Troubles de la personnalité :</strong> antisociale, borderline<br>\n              <strong><span class=\"nc-red_bg\">État de stress post-traumatique</span></strong><br>\n              <strong>Troubles anxieux</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Addictives</span></td>\n            <td>\n              Association à d'<span class=\"nc-red_bg\">autres addictions</span> aux <strong>substances psychoactives</strong> : <span>alcool</span>, <span class=\"nc-pink nc-bold\">cocaïne</span>, <span>benzodiazépines</span>, <span>tabac</span><br>\n              Addictions <strong>comportementales</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Toute addiction impose la recherche systématique d'une <strong>comorbidité psychiatrique</strong> et d'une <strong>polyconsommation</strong> — elles aggravent le pronostic et conditionnent la prise en charge.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span><span class=\"nc-red_bg\">Trouble bipolaire</span></span> · 66 — Trouble dépressif · 76 — Addiction à l'<span>alcool</span> · 77 — Addiction aux psychotropes</em></p><p>Rechercher <span class=\"nc-orange_bg\">dépression</span> et suicide pendant la descente des stimulants, TSPT, TDAH et polyconsommation. Dater les symptômes avant de conclure à une psychose primaire.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"78-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un syndrome d’intoxication chronique","contenu":"<div class=\"notion-course\"><p>Le <strong><span>syndrome d'intoxication chronique</span></strong> regroupe les manifestations <span class=\"nc-red nc-bold\">durables</span> liées à une consommation répétée et prolongée.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Manifestations de l'intoxication chronique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Cannabis</span></td>\n            <td>\n              <strong><span class=\"nc-red nc-bold\">Altération des performances cognitives</span> :</strong> <span class=\"nc-blue_bg\">troubles de la </span><span><span class=\"nc-blue_bg\">mémoire</span></span> ; atteinte des <span class=\"nc-blue_bg\">fonctions exécutives</span> (décision, inhibition) ; <span class=\"nc-blue_bg\">difficultés </span><span><span class=\"nc-blue_bg\">attentionnelles</span></span><br>\n              <strong><span class=\"nc-red nc-bold\">Syndrome amotivationnel</span></strong> = <span class=\"nc-red_bg\">indifférence affective</span> + <span class=\"nc-red_bg\">désinvestissement des relations sociales</span> + baisse des performances scolaires ou professionnelles\n            </td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-pink nc-bold\">Cocaïne</span></span></td>\n            <td>\n              Altération des capacités <span>attentionnelles</span> et <span>mnésiques</span> ; atteinte des <span class=\"nc-blue_bg\">fonctions exécutives</span><br>\n              <span><span class=\"nc-purple_bg\">Atrophie</span></span><span class=\"nc-purple_bg\"> possible des régions</span> <strong><span class=\"nc-purple_bg nc-bold\">préfrontales</span></strong> et <strong><span class=\"nc-purple_bg nc-bold\">temporales</span></strong>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Amphétamines</span></td>\n            <td>\n              <strong>Signes généraux :</strong> <span>asthénie</span> ; <span>perte de poids</span> (effet anorexigène) ; <span class=\"nc-orange_bg\">troubles du sommeil</span><br>\n              <strong>Psychiatriques :</strong> <span class=\"nc-orange_bg\">anxiété</span>, troubles de l'humeur, symptômes psychotiques transitoires<br>\n              <strong>Autres organes :</strong> atteinte rénale, digestive et hépatique ; <span>œdème pulmonaire</span> ; troubles du <span class=\"nc-orange nc-bold\">rythme</span> <span class=\"nc-orange nc-bold\">cardiaque</span> ; sécheresse buccale\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Mot-clé EDN.</strong> Le <strong><span class=\"nc-red nc-bold\">syndrome amotivationnel</span></strong> du cannabis (<span class=\"nc-red_bg\">indifférence affective</span>, désinvestissement social, chute des performances) est une notion classiquement tombable.</div><div class=\"callout\"><p><span class=\"nc-red nc-bold\">Syndrome amotivationnel</span> : description non spécifique, ne prouvant pas seule la responsabilité du cannabis. Rechercher <span class=\"nc-orange_bg\">dépression</span>, sommeil, contexte social et autres consommations.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"78-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un syndrome de sevrage","contenu":"<div class=\"notion-course\"><p>Le <strong><span>syndrome de sevrage</span></strong> survient à l'arrêt ou à la réduction d'une consommation, et témoigne d'une <strong>dépendance physique</strong>.</p>\n      <table>\n        <thead><tr><th>Famille</th><th>Délai / durée</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Cannabis</span></td>\n            <td>Apparition en <span>24-72 h</span> ; maximal la 1ʳᵉ semaine ; durée <span>1-<span class=\"nc-pink nc-bold\">3 semaines</span></span> (sommeil <span class=\"nc-pink_bg\">jusqu'à </span><span><span class=\"nc-pink_bg\">1 mois</span></span>) ; concerne <span>10-40 %</span> des usagers</td>\n            <td><span class=\"nc-blue_bg\">Irritabilité</span>, humeur triste, <span class=\"nc-blue_bg\">agressivité</span>, <span class=\"nc-orange_bg\">anxiété</span>, nervosité ; <span class=\"nc-orange nc-bold\">troubles du sommeil</span> (<span class=\"nc-orange_bg\">insomnie</span>, cauchemars) ; baisse de l'appétit ; signes physiques : <span><span class=\"nc-blue_bg\">douleurs abdominales</span></span>, <span class=\"nc-blue_bg\">tremblements</span>, <span class=\"nc-blue_bg\">sudation</span>, <span><span class=\"nc-blue_bg\">fièvre</span></span>, <span><span class=\"nc-blue_bg\">céphalées</span></span></td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-pink nc-bold\">Cocaïne</span></span></td>\n            <td><span class=\"nc-pink nc-bold\">Quelques heures</span> après l'arrêt ; durée <span class=\"nc-pink nc-bold\">plusieurs semaines</span></td>\n            <td>Tableau <strong>pseudo-dépressif</strong> : <span class=\"nc-blue_bg\">humeur dysphorique</span> ; <span class=\"nc-blue_bg\">ralentissement psychomoteur</span> ou <span class=\"nc-blue_bg\">agitation</span> ; <span>asthénie</span> ; <span><span class=\"nc-blue_bg\">hypersomnie</span></span> ; <span class=\"nc-blue_bg\">augmentation de l'appétit</span></td>\n          </tr>\n          <tr>\n            <td><span>Amphétamines</span></td>\n            <td><span class=\"nc-pink nc-bold\">Quelques</span> <span class=\"nc-pink nc-bold\">jours</span> après l'arrêt ; durée <span>1-2 <span class=\"nc-pink nc-bold\">semaines</span></span></td>\n            <td><span class=\"nc-orange_bg\">Dysphorie</span>, <span class=\"nc-orange_bg\">anxiété</span>, <span><span class=\"nc-orange_bg\">dépression</span></span> avec <span class=\"nc-orange_bg\">anhédonie</span> → <span><span class=\"nc-red nc-bold\">risque suicidaire</span></span> ; <span>asthénie</span> intense ; <span class=\"nc-blue_bg\">augmentation de l'appétit</span> ; <span class=\"nc-orange_bg\">troubles du sommeil</span> et de la <span class=\"nc-orange_bg\">concentration</span></td>\n          </tr>\n          <tr>\n            <td><span>Opiacés</span></td>\n            <td><span class=\"nc-pink nc-bold\">Héroïne</span> : <span>6-12 h</span> après la dernière prise, durée <span>3-7 <span class=\"nc-pink nc-bold\">jours</span></span> · <span class=\"nc-pink_bg\">méthadone</span> : après <span>2-4 <span class=\"nc-pink nc-bold\">jours</span></span>, durée jusqu'à <span><span class=\"nc-pink nc-bold\">3 semaines</span></span></td>\n            <td>\n              <strong>Généraux :</strong> tableau pseudo-grippal — <span><span class=\"nc-red nc-bold\">fièvre</span></span>, <span><span class=\"nc-blue_bg\">frissons</span></span>, <span>myalgies</span>, <span><span class=\"nc-blue nc-bold\">anorexie</span></span>, <span><span class=\"nc-blue nc-bold\">diarrhée</span></span>, <span><span class=\"nc-blue nc-bold\">nausées</span></span>/<span><span class=\"nc-blue nc-bold\">vomissements</span></span><br>\n              <strong>Neurovégétatifs :</strong> <span><span class=\"nc-red nc-bold\">mydriase</span></span>, <span class=\"nc-blue_bg\">bâillements</span>, larmoiement, <span class=\"nc-blue_bg\">rhinorrhée</span>, <span><span class=\"nc-brown_bg\">tachycardie</span></span>, <span><span class=\"nc-orange_bg\">HTA</span></span>, <span class=\"nc-brown_bg\">hypersudation</span>, horripilation<br>\n              <strong>Psychiatriques :</strong> <span class=\"nc-orange_bg\">anxiété</span>, <span class=\"nc-blue_bg\">irritabilité</span>, <span class=\"nc-orange_bg\">insomnie</span>, <span class=\"nc-orange_bg\">agitation</span>, <span><span class=\"nc-red_bg\">craving</span></span>\n            </td>\n          </tr>\n          <tr>\n            <td><span>GHB / GBL</span></td>\n            <td><span>1-4 h</span> après la dernière prise ; pic à <span>24 h</span> ; durée ≈ <span>9 <span class=\"nc-pink nc-bold\">jours</span></span></td>\n            <td><span class=\"nc-orange_bg\">Insomnie</span>, <span class=\"nc-blue_bg\">tremblements</span>, <span><span class=\"nc-red_bg\">confusion</span></span>, <span><span class=\"nc-blue nc-bold\">nausées</span></span>/<span><span class=\"nc-blue nc-bold\">vomissements</span></span>, puis <span>tachycardie</span>, <span><span class=\"nc-red_bg\">HTA</span></span>, agitation, <span>convulsions</span>, <span class=\"nc-red_bg\">hallucinations</span>, délirium</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout\"><p>Opioïdes : sevrage avec <span class=\"nc-red nc-bold\">mydriase</span>, à l’opposé du myosis souvent observé en surdose. GHB/GBL : sevrage potentiellement grave, avis urgent. Après kétamine, <span class=\"nc-red_bg\">craving</span> et symptômes psychiques peuvent exister sans syndrome physique typique bien codifié.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":2},{"id":"78-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un usage à risque","contenu":"<div class=\"notion-course\"><h4>Risque même sans addiction</h4><ul><li>Produit, puissance incertaine, quantité, voie, contexte, associations et antécédents.</li><li>Risques aigus : <span class=\"nc-orange_bg\">dépression</span> respiratoire, événement cardiovasculaire, hyperthermie, accident ou violence.</li><li>Partage de matériel, infection, conduite et activité sexuelle avec consentement altéré.</li><li>Aucun seuil universel sûr ; le statut légal ne remplace pas l’évaluation clinique.</li><li>Usage à risque : risque sans dommage encore établi, justifiant prévention et réduction des risques.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"78-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un usage nocif, d’une dépendance","contenu":"<div class=\"notion-course\"><p>Avec l'<strong>usage à risque</strong> (objectif précédent), l'<strong>usage nocif</strong> et la <strong>dépendance</strong> sont les deux véritables <strong>troubles liés à l'usage</strong> de substance. L'usage nocif n'est pas une addiction, mais ses répercussions en font un « trouble » ; la dépendance constitue le trouble addictif proprement dit.</p>\n      <table>\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span>Usage nocif</span><br>(<span>CIM-10</span>)</td><td>Mode de consommation <strong>préjudiciable à la santé</strong>, entraînant des <strong>dommages avérés</strong> physiques ou psychiques, <strong>sans remplir les critères de dépendance</strong> ; le patient ne fait pas le lien entre dommage et consommation</td></tr>\n          <tr><td><span>Dépendance</span><br>(<span>CIM-10</span>)</td><td>\n            <strong>Dépendance physique :</strong> objectivée par la <span>tolérance</span> (besoin d'augmenter les doses) et par le <span>syndrome de sevrage</span> à l'arrêt<br>\n            <strong>Dépendance psychique :</strong> dominée par le <span><span class=\"nc-red_bg\">craving</span></span> — envie irrépressible de consommer\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Critères de dépendance — <span>CIM-10</span>.</strong> Diagnostic de certitude si <strong>≥ 3 manifestations</strong> présentes <strong>simultanément au cours de la dernière année</strong> :\n        <ul>\n          <li><strong><span class=\"nc-red_bg\">Craving</span></strong> : désir puissant ou compulsif d'utiliser la substance ;</li>\n          <li><strong>Perte de contrôle</strong> de l'usage (difficultés à contrôler le début, l'interruption ou le niveau de consommation) ;</li>\n          <li><strong>Syndrome de sevrage</strong> physiologique à l'arrêt ou la réduction (ou réutilisation de la substance pour le soulager) ;</li>\n          <li><strong>Tolérance</strong> : besoin d'une quantité plus importante pour obtenir le même effet ;</li>\n          <li><strong>Abandon des autres intérêts</strong> et sources de plaisir, et temps croissant passé à se procurer/consommer la substance ou à récupérer de ses effets ;</li>\n          <li><strong>Poursuite de la consommation malgré les dommages</strong> manifestement nocifs.</li>\n        </ul>\n      </div>\n      <div><p>DSM-5 : 2–3 critères léger, 4–5 modéré, ≥6 sévère, sur 12 mois. Les classifications se recouvrent partiellement, sans correspondance automatique entre dépendance CIM-10 et sévérité DSM-5.</p></div><div class=\"callout\"><p>Tolérance et sevrage sous opioïde prescrit ne suffisent pas à diagnostiquer un trouble de l’usage. Rechercher les critères comportementaux et le retentissement.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":2},{"id":"78-12","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications","contenu":"<div class=\"notion-course\"><h4>Complications selon produit et pratique</h4><table><thead><tr><th>Produit/pratique</th><th>Complications</th></tr></thead><tbody><tr><td>Cannabis</td><td><span class=\"nc-orange_bg\">Anxiété</span>, psychose induite/aggravée, <span class=\"nc-orange_bg\">troubles cognitifs</span> ; bronchite si fumé ; hyperémèse cannabinoïde. Liens avec cancers variables et difficiles à séparer du tabac.</td></tr><tr><td><span class=\"nc-pink nc-bold\">Cocaïne</span></td><td>Syndrome coronarien, arythmie, dissection, AVC, convulsions ; lésions ORL du sniff, pulmonaires du crack ; <span class=\"nc-orange_bg\">dépression</span>/suicide.</td></tr><tr><td>Amphétaminiques/MDMA</td><td>Hyperthermie, rhabdomyolyse, insuffisance rénale, atteintes cardiovasculaires ; <span class=\"nc-red_bg\">hyponatrémie</span> avec MDMA, notamment après excès d’eau.</td></tr><tr><td>Opioïdes</td><td>Surdose respiratoire, constipation, troubles endocriniens ; sevrage néonatal possible. Soins adaptés pendant la grossesse.</td></tr><tr><td>Injection et partage</td><td><span class=\"nc-orange_bg\">Abcès</span>, endocardite, <span class=\"nc-purple_bg\">VIH</span>/<span class=\"nc-purple_bg\">VHB</span>/<span class=\"nc-purple_bg\">VHC</span> ; lymphœdème des mains après injections répétées ; risques sexuels associés.</td></tr><tr><td>Kétamine</td><td>Cystite douloureuse et atteinte urinaire, complications biliaires, cognitives et psychiatriques.</td></tr><tr><td>GHB/NPS</td><td>Coma, <span class=\"nc-orange_bg\">dépression</span> respiratoire ou toxicité stimulante/sérotoninergique selon substance.</td></tr></tbody></table><div class=\"callout\"><p>EVALI : lésion pulmonaire associée au vapotage, notamment de produits contaminés ; pas une conséquence de tout cannabis. Les conséquences sociales ne sont ni constantes ni un destin de l’usager.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":1},{"id":"78-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens biologiques","contenu":"<div class=\"notion-course\"><h4>Examens ciblés</h4><ul><li>Urgence : glycémie, ECG, ionogramme, fonction rénale, CK/gaz du sang/troponine selon syndrome ; ne pas attendre la toxicologie pour traiter.</li><li>Urines : fenêtre de détection, faux résultats et produits non recherchés ; un résultat positif ne mesure ni gravité ni causalité.</li><li>Suivi : VIH/VHB/VHC selon exposition, vaccination VHB, bilan somatique et santé sexuelle.</li><li>Traitement opioïde : clinique, interactions et tests urinaires selon indication et réglementation, sans remplacer l’entretien.</li><li><span class=\"nc-pink_bg\">Méthadone</span> : <span class=\"nc-blue_bg\">ECG</span>, QT et interactions ; évaluation d’une grossesse si pertinente.</li><li>Hémocultures/prélèvements selon suspicion infectieuse, pas un panel automatique à toute surdose.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://base-donnees-publique.medicaments.gouv.fr/medicament/61687452/extrait\" target=\"_blank\" rel=\"noopener noreferrer\">ANSM · RCP Méthadone AP-HP sirop, mai 2026</a></li></ul><p></p></details>","frequence":0},{"id":"78-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge","contenu":"<div class=\"notion-course\"><p>La prise en charge d'une addiction est <strong>globale et multimodale</strong> : elle associe une réponse <span>médicale</span>, <span>psychosociale</span> et <span>communautaire</span>. Elle s'appuie sur l'<strong>alliance thérapeutique</strong> et les <strong>entretiens motivationnels</strong>.</p>\n      <p>Elle peut viser autant l'<strong>arrêt</strong> de la consommation que la simple <strong>réduction des consommations et des dommages</strong> — l'objectif est négocié avec le patient.</p>\n      <p><strong><span>Réduction des risques et des dommages (RDRD).</span></strong> Stratégie visant à réduire les risques sanitaires liés à l'usage de substances et aux pratiques sexuelles associées, sans exiger l'arrêt de la consommation.</p>\n      <table>\n        <thead><tr><th>Volet</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><span>Acteurs</span></td><td>\n            <strong><span><span class=\"nc-yellow_bg\">CAARUD</span></span> :</strong> centres d'accueil et d'accompagnement à la réduction des risques pour usagers de drogues<br>\n            <strong><span><span class=\"nc-yellow_bg\">CSAPA</span></span> :</strong> centres de soins, d'accompagnement et de prévention en addictologie\n          </td></tr>\n          <tr><td><span>Mesures</span></td><td>\n            Accueil sans condition, quelle que soit la situation de l'usager<br>\n            Information sur les risques et leur prévention<br>\n            Distribution de matériel de prévention : seringues, préservatifs, kits crack<br>\n            Salles de consommation à moindre risque ; récupération du matériel usagé<br>\n            Accès aux droits et aux soins ; orientation vers les dispositifs spécialisés ; groupes d'entraide\n          </td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 73 — Techniques psychothérapeutiques · 74 — Psychotropes</em></p><div class=\"callout\"><p>Prévenir la surdose : <span class=\"nc-yellow_bg\">naloxone</span> à emporter, formation de l’entourage, éviter associations sédatives et anticiper la perte de tolérance après arrêt, hospitalisation ou incarcération.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://ansm.sante.fr/actualites/surdosage-et-overdose-dopioides-point-sur-loffre-therapeutique-de-la-naloxone-en-france\" target=\"_blank\" rel=\"noopener noreferrer\">ANSM · Naloxone et surdose d’opioïdes</a></li></ul><p></p></details>","frequence":1},{"id":"78-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement de l’intoxication aiguë","contenu":"<div class=\"notion-course\"><h4>Urgence avant identification exhaustive</h4><ol><li>Secours si respiration anormale, inconscience, convulsion, douleur thoracique ou hyperthermie. ABCDE, ventilation et réanimation selon besoin.</li><li>Opioïdes : <span class=\"nc-yellow_bg\">naloxone</span> sans attendre un test, doses répétées selon réponse et notice ; restaurer la ventilation sans rechercher un réveil brutal complet.</li><li>Surveiller la récidive : opioïdes souvent plus <span class=\"nc-red nc-bold\">durables</span> que <span class=\"nc-yellow_bg\">naloxone</span> ; répétition/perfusion et observation adaptées. Pas de plafond universel à 2 mg ni de surveillance fixée à quatre <span class=\"nc-pink nc-bold\">heures</span>.</li><li>Stimulants : calme, benzodiazépines titrées si agitation/convulsions, refroidissement et traitement des complications ; avis toxicologique.</li><li>Cannabis/hallucinogènes : réassurance/surveillance si forme simple ; traitement sélectionné si sévère, sans hydroxyzine obligatoire.</li><li>Syndrome sérotoninergique : arrêt des produits, support et avis spécialisé ; <span class=\"nc-pink_bg\">cyproheptadine</span> non automatique devant toute hyperthermie.</li></ol><div class=\"callout\"><p>Kit de <span class=\"nc-yellow_bg\">naloxone</span> : utiliser selon notice, renouveler si absence de réponse après 2–3 <span class=\"nc-pink nc-bold\">minutes</span> ; appeler le 15/112 et assurer les gestes de secours.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://ansm.sante.fr/actualites/surdosage-et-overdose-dopioides-point-sur-loffre-therapeutique-de-la-naloxone-en-france\" target=\"_blank\" rel=\"noopener noreferrer\">ANSM · Naloxone et surdose d’opioïdes</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3215131/fr/bon-usage-des-medicaments-opioides-antalgie-prevention-et-prise-en-charge-du-trouble-de-l-usage-et-des-surdoses\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Opioïdes, trouble de l’usage et surdoses, 2022</a></li></ul><p></p></details>","frequence":0},{"id":"78-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement du syndrome de sevrage","contenu":"<div class=\"notion-course\"><h4>Adapter le sevrage</h4><table><thead><tr><th>Produit</th><th>Prise en charge</th></tr></thead><tbody><tr><td>Cannabis</td><td>Soutien, sommeil, symptômes et <span class=\"nc-red_bg\">craving</span> ; pas de médicament spécifique de routine.</td></tr><tr><td>Stimulants</td><td>Surveiller <span class=\"nc-orange_bg\">dépression</span>/suicide, repos, nutrition, suivi psychosocial ; pas de sédatif automatique.</td></tr><tr><td>Opioïdes</td><td>Proposer traitement agoniste et soins symptomatiques ; prévenir surdose après perte de tolérance. Sevrage seul ≠ traitement durable.</td></tr><tr><td>GHB/GBL</td><td>Délirium/convulsions possibles : avis urgent, souvent hospitalisation, traitement spécialisé.</td></tr></tbody></table><div class=\"callout\"><p>« Éviter les benzodiazépines dans tout sevrage » est faux : leur place dépend du produit et du contexte. Ne pas arrêter brutalement un traitement agoniste pendant une grossesse.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"78-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement de la dépendance","contenu":"<div class=\"notion-course\"><h4>Traitement durable</h4><ul><li>Opioïdes : <span class=\"nc-pink_bg\">méthadone</span> ou <span class=\"nc-pink_bg\">buprénorphine</span>, avec/sans <span class=\"nc-yellow_bg\">naloxone</span> selon formulation, intégrées aux soins médicaux, psychologiques et sociaux.</li><li>Durée individualisée, parfois sans limite prédéfinie ; l’arrêt du médicament n’est pas une condition du rétablissement.</li><li>Autres produits : interventions motivationnelles/comportementales, comorbidités, soutien social et réduction des risques ; pas de substitution autorisée de routine pour cannabis/stimulants.</li><li>Infections, vaccination, santé sexuelle et protection des proches selon besoins.</li><li>Reprise : réadapter les soins sans culpabilisation ni rupture.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"78-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la prescription d’un traitement substitutif aux opiacés (TSO)","contenu":"<div class=\"notion-course\"><h4>Traitements agonistes opioïdes</h4><table><thead><tr><th>Traitement</th><th>Prescription</th></tr></thead><tbody><tr><td><span class=\"nc-pink_bg\">Méthadone</span> sirop</td><td>Initiation par médecin de CSAPA ou hospitalier habilité ; relais organisé. Ordonnance sécurisée, 14 jours maximum, fractions de 7 jours sauf mention adaptée.</td></tr><tr><td><span class=\"nc-pink_bg\">Méthadone</span> gélule</td><td>Relais stabilisé après au moins un an de sirop ; prescription initiale semestrielle spécialisée, <span class=\"nc-pink nc-bold\">28 jours</span> maximum.</td></tr><tr><td><span class=\"nc-pink_bg\">Buprénorphine</span> sublinguale ± <span class=\"nc-yellow_bg\">naloxone</span></td><td><span class=\"nc-green_bg\">Tout médecin</span> selon spécialité ; ordonnance sécurisée, 28 jours maximum, fractionnement adapté. Induction après sevrage suffisant pour éviter un sevrage précipité.</td></tr><tr><td>Formes prolongées</td><td><span class=\"nc-pink_bg\">Buprénorphine</span> injectable dans un cadre spécifique ; modalités propres, non transposables depuis la voie sublinguale.</td></tr></tbody></table><p>RCP <span class=\"nc-pink_bg\">méthadone</span> sirop mai 2026 : première <span class=\"nc-red_bg\">dose</span> habituellement 20–40 mg après évaluation, au moins dix <span class=\"nc-pink nc-bold\">heures</span> après la dernière prise ; titration surveillée selon réponse et accumulation. Ne pas enseigner 60 mg comme <span class=\"nc-red_bg\">dose</span> initiale standard.</p><ul><li>Évaluer consommations, sédation, interactions, QT, fonctions d’organe, grossesse et surdose ; proposer <span class=\"nc-yellow_bg\">naloxone</span>.</li><li>Pharmacie désignée, continuité des prescriptions, stockage inaccessible aux enfants.</li><li>Après interruption : réévaluer la tolérance, sans reprendre automatiquement l’ancienne dose.</li><li>Pas d’association de routine <span class=\"nc-pink_bg\">méthadone</span>–<span class=\"nc-pink_bg\">buprénorphine</span> ; transitions spécialisées.</li><li><span class=\"nc-yellow_bg\">Naloxone</span> du comprimé combiné : limite certains détournements, ne remplace pas le kit de secours.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues (78)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181b69c57ccbec9cfe3f5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cannabis</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418182a3e4eb9e7eceae1b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Cocaïne</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418184b95bce37ed26bef5?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Amphétamines</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181aeb574e633a1bf7fe7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Opiacés</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418112b80de48779514498?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Drogues de synthèse</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418175a69fef251a87fbc4?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Hallucinogènes, GHB/GBL, Kétamine</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://ansm.sante.fr/uploads/2021/10/27/20211027-marr-methadoneaphpsirop-gelule-brochure-patient-02-2021-10.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ANSM · Méthadone, document de bon usage</a></li><li><a href=\"https://base-donnees-publique.medicaments.gouv.fr/medicament/61687452/extrait\" target=\"_blank\" rel=\"noopener noreferrer\">ANSM · RCP Méthadone AP-HP sirop, mai 2026</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3215131/fr/bon-usage-des-medicaments-opioides-antalgie-prevention-et-prise-en-charge-du-trouble-de-l-usage-et-des-surdoses\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Opioïdes, trouble de l’usage et surdoses, 2022</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3419438/fr/buvidal-22022023-avis-ct19818\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Buvidal, buprénorphine prolongée</a></li></ul><p></p></details>","frequence":1,"liens":[{"href":"https://pharmacomedicale.org/medicaments/par-specialites/category/opiaces","label":"Pharmacomedicale — Opiacés"}]}],"astuces":[{"type":"piege","titre":"Surdose","contenu":"<div class=\"notion-course\"><p>Respiration d’abord, <span class=\"nc-yellow_bg\">naloxone</span> et secours ; surveiller la récidive.</p></div>"},{"type":"piege","titre":"Reprise","contenu":"<div class=\"notion-course\"><p>La perte de tolérance augmente le risque après interruption.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Toxidrome, produits, chronologie et complications ; distinguer intoxication, sevrage et trouble de l’usage.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Soins <span class=\"nc-red nc-bold\">durables</span>, réduction des risques et agoniste opioïde selon indication.</li></ul></div>","Examens complémentaires":"<div class=\"notion-course\"><ul><li>Examens orientés ; aucun test ne remplace la clinique.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf","label":"CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024) ↗"},{"href":"https://www.ofdt.fr/sites/ofdt/files/2025-01/dacc_2024.pdf","label":"OFDT · Drogues et addictions, chiffres clés 2025 ↗"},{"href":"https://www.ofdt.fr/cannabis-resine-herbe-huile-cbd-synthese-des-connaissances-1724","label":"OFDT · Cannabis, synthèse des connaissances ↗"},{"href":"https://base-donnees-publique.medicaments.gouv.fr/medicament/61687452/extrait","label":"ANSM · RCP Méthadone AP-HP sirop, mai 2026 ↗"},{"href":"https://ansm.sante.fr/actualites/surdosage-et-overdose-dopioides-point-sur-loffre-therapeutique-de-la-naloxone-en-france","label":"ANSM · Naloxone et surdose d’opioïdes ↗"},{"href":"https://www.has-sante.fr/jcms/p_3215131/fr/bon-usage-des-medicaments-opioides-antalgie-prevention-et-prise-en-charge-du-trouble-de-l-usage-et-des-surdoses","label":"HAS · Opioïdes, trouble de l’usage et surdoses, 2022 ↗"},{"href":"https://ansm.sante.fr/uploads/2021/10/27/20211027-marr-methadoneaphpsirop-gelule-brochure-patient-02-2021-10.pdf","label":"ANSM · Méthadone, document de bon usage ↗"},{"href":"https://www.has-sante.fr/jcms/p_3419438/fr/buvidal-22022023-avis-ct19818","label":"HAS · Buvidal, buprénorphine prolongée ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Respiration lente ou absente avec altération de conscience ?","detail":"<ul><li>Évoquer opioïdes, surtout avec myosis ; le myosis peut manquer.</li><li>Appeler les secours et rechercher autres causes/co-ingestions.</li></ul>","branches":[{"label":"Oui / suspicion","to":"ventiler"},{"label":"Non, exposition possible","to":"evaluer"}]},{"id":"ventiler","kind":"decision","label":"Libérer les voies aériennes et soutenir la ventilation","detail":"<ul><li>Réanimation si nécessaire ; naloxone dès que disponible selon dispositif/protocole.</li><li>Ne pas attendre un test toxicologique.</li></ul>","branches":[{"label":"Réponse respiratoire","to":"observer"},{"label":"Réponse insuffisante","to":"repeter"}]},{"id":"repeter","kind":"urgent","label":"Répéter/adapter la naloxone et poursuivre la réanimation","detail":"<ul><li>Dose, voie et relais selon réponse et produit ; avis spécialisé.</li><li>Absence de réponse : rechercher autre toxique ou affection associée.</li></ul>","branches":[]},{"id":"observer","kind":"urgent","label":"Surveiller une possible renarcotisation","detail":"<ul><li>Effet de certains opioïdes plus long que celui de la naloxone.</li><li>Durée d’observation et relais adaptés à la molécule et à l’évolution.</li></ul>","branches":[]},{"id":"evaluer","kind":"decision","label":"Examen, surveillance et informations d’exposition","detail":"<ul><li>Produit, dose, voie, horaire, tolérance et associations ; examens ciblés.</li></ul>","branches":[{"label":"Après stabilisation","to":"prevenir"}]},{"id":"prevenir","kind":"finish","label":"Prévenir la récidive et proposer des soins","detail":"<ul><li>Naloxone à emporter et formation de l’entourage, réduction des risques.</li><li>Perte de tolérance après interruption : risque accru ; proposer traitement du trouble de l’usage.</li></ul>","branches":[]}]},"cards":[{"i":"06d2ae358094","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Quelle est la définition et les différents types d'opiacés ?","a":"<div class=\"notion-course\"><p>Opiacés : composés <span class=\"nc-yellow_bg\">naturels</span> de l’opium et dérivés. Opioïdes : terme large incluant les <span class=\"nc-yellow_bg\">produits synthétiques</span> agissant sur leurs récepteurs.</p></div>"},{"i":"58207150c1ef","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Que sont les drogues de synthèse (NPS/NSP) ?","a":"<div class=\"notion-course\"><p>Nouveaux produits psychoactifs de familles diverses ; composition et réglementation évoluent. Ne garantit ni absence de contrôle ni sécurité.</p></div>"},{"i":"60962fac051c","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Que sont les amphétamines et quels sont leurs principaux représentants ?","a":"<div class=\"notion-course\"><p>Les amphétamines sont des <strong>dérivés amphétaminiques de synthèse</strong>. Les principaux représentants incluent l'<span class=\"nc-yellow_bg\">amphétamine</span>, le <strong><span class=\"nc-pink nc-bold\">MDMA</span>/ecstasy</strong> et la <strong><span class=\"nc-pink nc-bold\">méthamphétamine</span></strong>.</p></div>"},{"i":"7bf42ae964e9","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Quelle est la définition et les caractéristiques principales du cannabis ?","a":"<div class=\"notion-course\"><p>Le cannabis est une substance issue de la plante <strong>Cannabis sativa</strong>. C'est la <span class=\"nc-yellow_bg\">substance illicite la plus consommée en France</span>.</p></div>"},{"i":"90299b4815a0","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Quelle est la définition et l'origine de la cocaïne ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-pink nc-bold\">cocaïne</span> est une substance <strong>stimulante</strong> extraite des feuilles de <strong>coca</strong>, principalement cultivées en Amérique du Sud.</p></div>"},{"i":"ab311acb770e","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Comment est défini le mésusage pour les substances illicites mentionnées ?","a":"<div class=\"notion-course\"><p>Toute prise peut présenter des risques, sans prouver une addiction. Évaluer usage à risque, dommages et trouble de l’usage.</p></div>"},{"i":"0cb8e2b31b49","n":78,"o":"78-2","u":"Définition","t":"Connaître les principes actifs","q":"Quelles sont les différentes formes du principe actif de la cocaïne ?","a":"<div class=\"notion-course\"><p><span class=\"nc-pink nc-bold\">Chlorhydrate</span> en poudre et <span class=\"nc-yellow_bg\">forme</span> base (crack/<span class=\"nc-yellow_bg\">free base</span>) : même substance active, voies et cinétiques différentes.</p></div>"},{"i":"25a8315a171f","n":78,"o":"78-2","u":"Définition","t":"Connaître les principes actifs","q":"Quels sont les différents types d'opiacés classés selon leur origine et citez un exemple pour chaque type ?","a":"<div class=\"notion-course\"><p><span class=\"nc-yellow_bg\">Naturels</span> : morphine, codéine. <span class=\"nc-yellow_bg\">Semi-synthétiques</span> : <span class=\"nc-pink nc-bold\">héroïne</span>, oxycodone, <span class=\"nc-pink_bg\">buprénorphine</span>. Synthétiques : <span class=\"nc-pink_bg\">méthadone</span>, fentanyl, tramadol.</p></div>"},{"i":"7abaca689921","n":78,"o":"78-2","u":"Définition","t":"Connaître les principes actifs","q":"Quel est le principe psychoactif du cannabis, sa classe et ses récepteurs cibles ?","a":"<div class=\"notion-course\"><p>Le principal principe psychoactif du cannabis est le <strong>Δ9-THC (delta-9-tétrahydrocannabinol)</strong>. C'est un <strong>agoniste des <span class=\"nc-red nc-bold\">récepteurs cannabinoïdes</span> <span class=\"nc-red nc-bold\">CB1</span> et CB2</strong>.</p></div>"},{"i":"aef14789c09f","n":78,"o":"78-2","u":"Définition","t":"Connaître les principes actifs","q":"Citez des exemples de drogues de synthèse dont le principe actif est de type cannabinoïde ou cathinone.","a":"<div class=\"notion-course\"><p><span class=\"nc-yellow_bg\">Cannabinoïdes de synthèse</span> (Spice…) et <span class=\"nc-yellow_bg\">cathinones</span> (<span class=\"nc-pink_bg\">méphédrone</span>, <span class=\"nc-pink_bg\">MDPV</span>, 3-MMC…). Effets parfois <span class=\"nc-red nc-bold\">puissants</span> et imprévisibles.</p></div>"},{"i":"ccf6a4e5ec54","n":78,"o":"78-2","u":"Définition","t":"Connaître les principes actifs","q":"Quels sont les principaux principes actifs des amphétamines et de leurs dérivés ?","a":"<div class=\"notion-course\"><p>Les principaux principes actifs de cette famille incluent :</p><ul><li>L'<strong><span class=\"nc-yellow_bg\">amphétamine</span></strong>.</li><li>La <strong>MDMA (ecstasy)</strong>.</li><li>La <strong><span class=\"nc-pink nc-bold\">méthamphétamine</span></strong>, qui présente des effets particulièrement <span class=\"nc-red nc-bold\">puissants</span> et un fort <span class=\"nc-red nc-bold\">potentiel addictif</span>.</li></ul></div>"},{"i":"eb25e06c230f","n":78,"o":"78-3","u":"Définition","t":"Connaître les modes de consommation et leurs effets","q":"Pourquoi l’association opioïde–alcool–BZD est-elle dangereuse ?","a":"<div class=\"notion-course\"><ul><li>Addition des effets dépresseurs : coma et <span class=\"nc-orange_bg\">dépression</span> respiratoire.</li></ul></div>"},{"i":"c014804c72e9","n":78,"o":"78-4","u":"Définition","t":"Connaître les voies d’administration","q":"Quel piège accompagne l’ingestion de cannabis ?","a":"<div class=\"notion-course\"><ul><li>Début retardé et effet prolongé favorisant répétition des prises et <span class=\"nc-red nc-bold\">surdosage</span>.</li></ul></div>"},{"i":"1a214f2e2700","n":78,"o":"78-5","u":"Définition","t":"Connaître la prévalence de l’utilisation des principales drogues psychoactives","q":"Expérimentation et usage dans l’année sont-ils équivalents ?","a":"<div class=\"notion-course\"><ul><li>Non : préciser période et population. <span class=\"nc-pink nc-bold\">Cocaïne</span> OFDT 2023 : 9,4 % expérimentation, 2,7 % dans l’année.</li></ul></div>"},{"i":"c13781f75f23","n":78,"o":"78-6","u":"Définition","t":"Connaître la définition de l’intoxication aiguë","q":"Quelle triade évoque une surdose opioïde ?","a":"<div class=\"notion-course\"><ul><li>Trouble de conscience, bradypnée/apnée et souvent myosis ; traiter sans attendre un test.</li></ul></div>"},{"i":"b6c9d56a4a94","n":78,"o":"78-7","u":"Définition","t":"Connaître les comorbidités psychiatriques et addictives","q":"Quelle urgence psychiatrique rechercher à la descente des stimulants ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-orange_bg\">Dépression</span> et suicide, agitation/psychose possibles.</li></ul></div>"},{"i":"25b1e3b9abc3","n":78,"o":"78-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un syndrome d’intoxication chronique","q":"Le syndrome amotivationnel prouve-t-il une intoxication au cannabis ?","a":"<div class=\"notion-course\"><ul><li>Non : non spécifique, rechercher <span class=\"nc-orange_bg\">dépression</span> et autres causes.</li></ul></div>"},{"i":"78450f9e88e6","n":78,"o":"78-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un syndrome de sevrage","q":"Quel sevrage peut rapidement être grave parmi GHB et cannabis ?","a":"<div class=\"notion-course\"><ul><li>GHB/GBL : délirium et convulsions ; avis urgent.</li></ul></div>"},{"i":"58a51bfe7cfc","n":78,"o":"78-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un usage à risque","q":"L’absence de dépendance exclut-elle une complication d’une drogue ?","a":"<div class=\"notion-course\"><ul><li>Non : complication aiguë possible dès une prise.</li></ul></div>"},{"i":"a4753b6db3f7","n":78,"o":"78-11","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un usage nocif, d’une dépendance","q":"Tolérance et sevrage sous opioïde prescrit suffisent-ils à poser une addiction ?","a":"<div class=\"notion-course\"><ul><li>Non : rechercher les critères comportementaux et le retentissement.</li></ul></div>"},{"i":"929645001cb1","n":78,"o":"78-12","u":"Suivi et/ou pronostic","t":"Connaître les principales complications","q":"Quelle complication urinaire évoquer après usages répétés de kétamine ?","a":"<div class=\"notion-course\"><ul><li>Cystite douloureuse, pollakiurie/hématurie, atteinte des voies urinaires.</li></ul></div>"},{"i":"080577a6065a","n":78,"o":"78-13","u":"Examens complémentaires","t":"Connaître les indications des examens biologiques","q":"Un dépistage urinaire négatif élimine-t-il une intoxication ?","a":"<div class=\"notion-course\"><ul><li>Non : délais, sensibilité et produits non recherchés ; clinique prioritaire.</li></ul></div>"},{"i":"71fcbb02871b","n":78,"o":"78-14","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Que prévoir pour prévenir une surdose opioïde ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-yellow_bg\">Naloxone</span> et formation, éviter associations sédatives, expliquer perte de tolérance et maintenir le soin.</li></ul></div>"},{"i":"6f7c0d09b5c3","n":78,"o":"78-15","u":"Prise en charge","t":"Connaître les modalités du traitement de l’intoxication aiguë","q":"Le réveil après naloxone autorise-t-il une sortie immédiate ?","a":"<div class=\"notion-course\"><ul><li>Non : récidive respiratoire possible ; secours et surveillance adaptés.</li></ul></div>"},{"i":"1f0c0a8f8790","n":78,"o":"78-16","u":"Prise en charge","t":"Connaître les modalités du traitement du syndrome de sevrage","q":"Un sevrage opioïde isolé assure-t-il le traitement durable ?","a":"<div class=\"notion-course\"><ul><li>Non : reprise et surdose après perte de tolérance ; proposer traitement agoniste et suivi.</li></ul></div>"},{"i":"a7c2bec356a9","n":78,"o":"78-17","u":"Prise en charge","t":"Connaître les modalités du traitement de la dépendance","q":"Faut-il arrêter un agoniste opioïde à une échéance fixe ?","a":"<div class=\"notion-course\"><ul><li>Non : durée selon bénéfice, objectifs et stabilité.</li></ul></div>"},{"i":"a8fbc79d2e0f","n":78,"o":"78-18","u":"Prise en charge","t":"Connaître les modalités de la prescription d’un traitement substitutif aux opiacés (TSO)","q":"Quel risque si buprénorphine trop tôt après un agoniste opioïde ?","a":"<div class=\"notion-course\"><ul><li>Sevrage précipité ; induction avec signes de sevrage suffisants et protocole adapté.</li></ul></div>"},{"i":"4ab99f7671ef","n":78,"o":"78-18","u":"Prise en charge","t":"Connaître les modalités de la prescription d’un traitement substitutif aux opiacés (TSO)","q":"Que faire après plusieurs jours sans méthadone ?","a":"<div class=\"notion-course\"><ul><li>Réévaluer la tolérance et la reprise ; pas de retour automatique à l’ancienne dose.</li></ul></div>"},{"i":"256cc5890ba8","n":78,"o":"78-15","u":"Prise en charge","t":"Connaître les modalités du traitement de l’intoxication aiguë","q":"Existe-t-il un maximum universel de 2 mg de naloxone ?","a":"<div class=\"notion-course\"><ul><li>Non : répéter selon ventilation, produit et protocole ; des doses supplémentaires peuvent être nécessaires.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d9418125a6a3f76801db7974?pvs=204","reviewedAt":"2026-10-14","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddStatus":"Situations LiSA vérifiées le 14 octobre 2026 dans la session UNESS connectée.","algorithms":3,"lisaSituations":[{"number":340,"title":"Prise d’un toxique ou médicament potentiellement toxique","url":"https://livret.uness.fr/lisa/2026/Prise_volontaire_ou_involontaire_d%27un_toxique_ou_d%27un_m%C3%A9dicament_potentiellement_toxique_SDD-340","expectations":["Dater et quantifier l’exposition, reconnaître les toxidromes, évaluer la gravité et considérer un antidote adapté.","Organiser surveillance et orientation, évaluer intention suicidaire ou maltraitance et solliciter le centre antipoison selon la situation."],"verifiedAt":"2026-10-14"},{"number":292,"title":"Première consultation d’addictologie","url":"https://livret.uness.fr/lisa/2026/Premi%C3%A8re_consultation_d%27addictologie_SDD-292","expectations":["Caractériser usage nocif, dépendance ou addiction comportementale selon la classification utilisée ; rechercher sevrage, complications et comorbidités.","Évaluer les conséquences familiales, sociales et professionnelles, fixer des objectifs partagés et orienter ou proposer une substitution selon indication."],"verifiedAt":"2026-10-14"},{"number":293,"title":"Consultation de suivi addictologie","url":"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_addictologie_SDD-293","expectations":["Rechercher manque, nouveaux symptômes, complications et comorbidités ; apprécier efficacité, tolérance et qualité de vie.","Adapter prescription et accompagnement social ; la valorisation du stage inclut psychothérapie, entretien motivationnel et soutien des proches avec respect de la confidentialité."],"verifiedAt":"2026-10-14"}]}};
